def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opps = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opps.append((oid, opp))

    if len(alive_opps) == 0:
        return float(min(budget, 20.0))

    prev_bids = []
    cindy_prev = None
    urgent_opps = 0
    rich_opps = 0

    for oid, opp in alive_opps:
        if opp.get('budget', 0) >= DAILY_SALARY * 2:
            rich_opps += 1
        if opp.get('no_water_days', 0) >= 1 or opp.get('hp', 0) <= 3:
            urgent_opps += 1
        prev = opp.get('previous_trace', {}) or {}
        bid = prev.get('bid')
        if bid is not None:
            prev_bids.append(float(bid))
            if oid == 'Cindy':
                cindy_prev = float(bid)

    slots = int(supply // WATER_REQ)
    contested = slots <= 1

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = (sum(prev_bids) / len(prev_bids)) if prev_bids else 0.0

    if cindy_prev is None:
        cindy_prev = avg_prev

    if no_water_days >= 2 or hp <= 2:
        target = max(0.92 * DAILY_SALARY, cindy_prev + 6.0, min(highest_prev + 3.0, 0.98 * DAILY_SALARY))
        return float(min(budget, max(0.0, target)))

    if contested:
        if no_water_days >= 1 or hp <= 4:
            target = max(0.82 * DAILY_SALARY, cindy_prev + 4.0)
        else:
            target = max(0.58 * DAILY_SALARY, cindy_prev * 0.55)
            if urgent_opps >= 1:
                target = min(target, 0.52 * DAILY_SALARY)
        return float(min(budget, max(0.0, target)))

    target = 0.26 * DAILY_SALARY
    if cindy_prev > 0:
        target = max(target, min(cindy_prev * 0.22, 0.38 * DAILY_SALARY))
    if rich_opps >= 2 and day >= 7:
        target = max(target, 0.34 * DAILY_SALARY)
    if no_water_days >= 1:
        target = max(target, 0.48 * DAILY_SALARY)
    if hp <= 4:
        target = max(target, 0.54 * DAILY_SALARY)

    return float(min(budget, max(0.0, target)))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    hp = int(my_status.get('hp', 0))
    budget = float(my_status.get('budget', 0.0))
    no_water_days = int(my_status.get('no_water_days', 0))

    alive_opponents = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opponents.append((opp_id, opp))

    if not alive_opponents:
        return min(budget, DAILY_SALARY * 0.4)

    # Extract yesterday bids from previous_trace only
    prev_bids = []
    for _, opp in alive_opponents:
        prev = opp.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                prev_bids.append(float(b))
            except Exception:
                pass

    # Estimate competitive pressure from yesterday
    highest_prev_bid = max(prev_bids) if prev_bids else 0.0
    second_highest_prev_bid = 0.0
    if len(prev_bids) >= 2:
        s = sorted(prev_bids, reverse=True)
        second_highest_prev_bid = s[1]

    # Supply pressure: if supply is low, water is scarce; bid more.
    # Use a simple scarcity factor.
    scarcity = 0.0
    if MAX_SUPPLY > MIN_SUPPLY:
        scarcity = (MAX_SUPPLY - supply) / (MAX_SUPPLY - MIN_SUPPLY)
    scarcity = max(0.0, min(1.0, scarcity))

    # Decide aggressiveness based on our condition.
    # If we're close to death or already have many no-water days, bid very aggressively.
    urgent = (hp <= 2) or (no_water_days >= 2)

    if urgent:
        target = DAILY_SALARY * (0.9 + 0.1 * scarcity)  # ~81-99
    else:
        # If others previously bid high (Cindy survived), we must match/beat.
        # Otherwise, bid moderately above the likely floor.
        if highest_prev_bid >= DAILY_SALARY * 1.6:  # ~144+
            target = highest_prev_bid + (2.0 + 6.0 * scarcity)
        elif highest_prev_bid >= DAILY_SALARY * 1.1:
            target = max(DAILY_SALARY * (0.55 + 0.25 * scarcity), second_highest_prev_bid + 3.0)
        else:
            target = DAILY_SALARY * (0.5 + 0.25 * scarcity)

    # Clamp by budget and a reasonable cap to avoid overspending.
    # If budget is low, spend what we can.
    cap = max(DAILY_SALARY * 2.5, highest_prev_bid + 20.0)
    bid = min(budget, max(0.0, min(target, cap)))

    # If budget is extremely low, still bid something if urgent.
    if bid <= 0.0 and urgent:
        bid = min(budget, DAILY_SALARY * 0.2)

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
